const PROCESSING_FEE = 5;

export type StepResult = { premium: number };
export type ScenarioResult = { results: StepResult[] };

export const runScenario = (scenario: unknown): ScenarioResult => {
  return { results: [{ premium: PROCESSING_FEE }] };
};
